head.b:skin:
:root{
  --bg:#0b1020;
  --bg-elevated:#11182d;
  --bg-soft:#16203a;
  --bg-strong:#0f1530;
  --surface:#10182b;
  --surface-2:#18233f;
  --surface-3:#223255;
  --text:#f4f7fb;
  --text-soft:#c5d0e6;
  --text-muted:#90a0c0;
  --line:rgba(148,163,184,.18);
  --line-strong:rgba(148,163,184,.32);
  --accent:#5eead4;
  --accent-2:#7dd3fc;
  --accent-3:#22c55e;
  --danger:#f97316;
  --shadow:0 24px 70px rgba(0,0,0,.35);
  --shadow-soft:0 18px 40px rgba(6,10,24,.2);
  --radius:24px;
  --radius-sm:16px;
  --radius-xs:12px;
  --container:min(1180px, calc(100% - 32px));
  --font-body:'Roboto', sans-serif;
  --font-code:'JetBrains Mono', monospace;
  --header-height:76px;
}

html.light-mode{
  --bg:#f5f7fb;
  --bg-elevated:#ffffff;
  --bg-soft:#eef4ff;
  --bg-strong:#e5edff;
  --surface:#ffffff;
  --surface-2:#f8fbff;
  --surface-3:#edf3fe;
  --text:#0f172a;
  --text-soft:#334155;
  --text-muted:#64748b;
  --line:rgba(15,23,42,.1);
  --line-strong:rgba(15,23,42,.18);
  --shadow:0 24px 70px rgba(15,23,42,.08);
  --shadow-soft:0 18px 40px rgba(15,23,42,.07);
}

*{box-sizing:border-box}
html{scroll-behavior:smooth}
body{
  margin:0;
  font-family:var(--font-body);
  background:
    radial-gradient(circle at top left, rgba(34,197,94,.10), transparent 26%),
    radial-gradient(circle at top right, rgba(125,211,252,.12), transparent 24%),
    linear-gradient(180deg, var(--bg) 0%, var(--bg-elevated) 100%);
  color:var(--text);
  line-height:1.65;
  -webkit-font-smoothing:antialiased;
  text-rendering:optimizeLegibility;
}

a{color:inherit;text-decoration:none}
img{max-width:100%;display:block}
button,input,textarea{font:inherit}
::selection{background:rgba(94,234,212,.25);color:var(--text)}

.skip-link{
  position:absolute;
  left:-9999px;
  top:0;
}
.skip-link:focus{
  left:16px;
  top:16px;
  z-index:200;
  padding:10px 14px;
  border-radius:999px;
  background:var(--accent);
  color:#04212a;
}

.page-shell{
  min-height:100vh;
}

.site-header{
  position:sticky;
  top:0;
  z-index:120;
  backdrop-filter:blur(18px);
  background:rgba(11,16,32,.72);
  border-bottom:1px solid var(--line);
}
html.light-mode .site-header{
  background:rgba(245,247,251,.82);
}

.nav-wrap{
  width:var(--container);
  min-height:var(--header-height);
  margin:0 auto;
  display:flex;
  align-items:center;
  justify-content:space-between;
  gap:16px;
}

.brand{
  display:flex;
  align-items:center;
  gap:14px;
  min-width:0;
}

.brand-mark{
  width:46px;
  height:46px;
  border-radius:14px;
  display:grid;
  place-items:center;
  font-family:var(--font-code);
  font-weight:700;
  color:#04131b;
  background:linear-gradient(135deg, var(--accent), var(--accent-2));
  box-shadow:var(--shadow-soft);
}

.brand-copy{
  min-width:0;
}

.brand-copy strong{
  display:block;
  font-size:1rem;
  letter-spacing:.01em;
}

.brand-copy span{
  display:block;
  font-size:.88rem;
  color:var(--text-muted);
  white-space:nowrap;
  overflow:hidden;
  text-overflow:ellipsis;
}

.nav-actions{
  display:flex;
  align-items:center;
  gap:12px;
}

.nav-links{
  display:flex;
  align-items:center;
  gap:8px;
  flex-wrap:wrap;
}

.nav-link{
  padding:10px 14px;
  border-radius:999px;
  color:var(--text-soft);
  transition:background .25s ease,color .25s ease,transform .25s ease;
}

.nav-link:hover,
.nav-link:focus{
  background:var(--surface-2);
  color:var(--text);
  transform:translateY(-1px);
}

.theme-toggle,
.copy-button,
.search-toggle{
  border:1px solid var(--line);
  background:var(--surface);
  color:var(--text);
  border-radius:999px;
  padding:10px 14px;
  cursor:pointer;
  transition:transform .25s ease, border-color .25s ease, background .25s ease;
}

.theme-toggle:hover,
.copy-button:hover,
.search-toggle:hover{
  transform:translateY(-1px);
  border-color:var(--line-strong);
}

.search-panel{
  width:var(--container);
  margin:0 auto;
  padding:0 0 18px;
  display:none;
}

.search-panel.is-visible{
  display:block;
}

.search-card{
  background:var(--surface);
  border:1px solid var(--line);
  border-radius:18px;
  padding:18px;
  box-shadow:var(--shadow-soft);
}

.search-card form{
  display:flex;
  gap:12px;
  flex-wrap:wrap;
}

.search-card input[type="text"]{
  flex:1 1 220px;
  min-height:52px;
  background:var(--bg-soft);
  color:var(--text);
  border:1px solid var(--line);
  border-radius:14px;
  padding:0 16px;
}

.search-card button{
  min-height:52px;
  padding:0 20px;
  border:none;
  border-radius:14px;
  background:linear-gradient(135deg, var(--accent), var(--accent-2));
  color:#04212a;
  font-weight:700;
  cursor:pointer;
}

.hero{
  width:var(--container);
  margin:0 auto;
  padding:56px 0 24px;
  display:grid;
  grid-template-columns:minmax(0,1.5fr) minmax(280px,.95fr);
  gap:24px;
  align-items:stretch;
}

.hero-panel,
.hero-side,
.card,
.section-card,
.sidebar-card,
.post-card,
.feature-card,
.contact-card{
  background:linear-gradient(180deg, rgba(255,255,255,.03), rgba(255,255,255,.01));
  border:1px solid var(--line);
  border-radius:var(--radius);
  box-shadow:var(--shadow-soft);
}

html.light-mode .hero-panel,
html.light-mode .hero-side,
html.light-mode .card,
html.light-mode .section-card,
html.light-mode .sidebar-card,
html.light-mode .post-card,
html.light-mode .feature-card,
html.light-mode .contact-card{
  background:linear-gradient(180deg, rgba(255,255,255,.92), rgba(255,255,255,.82));
}

.hero-panel{
  padding:36px;
  position:relative;
  overflow:hidden;
}

.hero-panel:before{
  content:'';
  position:absolute;
  inset:auto -16% -35% auto;
  width:340px;
  height:340px;
  border-radius:50%;
  background:radial-gradient(circle, rgba(94,234,212,.18), transparent 68%);
  pointer-events:none;
}

.eyebrow{
  display:inline-flex;
  align-items:center;
  gap:8px;
  padding:8px 12px;
  border-radius:999px;
  background:rgba(94,234,212,.08);
  color:var(--accent);
  border:1px solid rgba(94,234,212,.16);
  font-size:.84rem;
  font-weight:700;
  letter-spacing:.08em;
  text-transform:uppercase;
}

.hero h1,
.section-heading h2,
.page-hero h1,
.post-title{
  margin:18px 0 12px;
  line-height:1.05;
  letter-spacing:-.04em;
}

.hero h1{
  font-size:clamp(2.5rem, 4.5vw, 4.8rem);
  max-width:12ch;
}

.hero p{
  max-width:62ch;
  color:var(--text-soft);
  font-size:1.06rem;
  margin:0 0 24px;
}

.hero-actions{
  display:flex;
  gap:12px;
  flex-wrap:wrap;
  margin-bottom:28px;
}

.button{
  display:inline-flex;
  align-items:center;
  justify-content:center;
  gap:8px;
  min-height:52px;
  padding:0 20px;
  border-radius:16px;
  font-weight:700;
  transition:transform .25s ease, border-color .25s ease, background .25s ease;
}

.button-primary{
  color:#04212a;
  background:linear-gradient(135deg, var(--accent), var(--accent-2));
}

.button-secondary{
  background:var(--surface);
  border:1px solid var(--line);
  color:var(--text);
}

.button:hover{
  transform:translateY(-1px);
}

.metric-grid{
  display:grid;
  grid-template-columns:repeat(3, minmax(0,1fr));
  gap:14px;
}

.metric{
  padding:18px;
  border-radius:18px;
  background:var(--bg-soft);
  border:1px solid var(--line);
}

.metric strong{
  display:block;
  font-size:1.35rem;
  line-height:1.1;
}

.metric span{
  display:block;
  margin-top:4px;
  font-size:.92rem;
  color:var(--text-muted);
}

.hero-side{
  padding:28px;
  display:grid;
  gap:18px;
}

.hero-stack{
  display:grid;
  gap:12px;
}

.stack-chip,
.tag,
.meta-pill{
  display:inline-flex;
  align-items:center;
  gap:8px;
  padding:9px 12px;
  border-radius:999px;
  background:var(--bg-soft);
  border:1px solid var(--line);
  color:var(--text-soft);
  font-size:.9rem;
}

.section{
  width:var(--container);
  margin:0 auto;
  padding:24px 0;
}

.section-heading{
  display:flex;
  align-items:end;
  justify-content:space-between;
  gap:16px;
  margin-bottom:20px;
}

.section-heading h2{
  font-size:clamp(1.8rem, 3vw, 2.8rem);
}

.section-heading p{
  margin:0;
  max-width:62ch;
  color:var(--text-muted);
}

.feature-grid,
.services-grid,
.resource-grid,
.testimonial-grid,
.project-grid,
.page-grid,
.footer-grid{
  display:grid;
  gap:18px;
}

.feature-grid{
  grid-template-columns:repeat(3, minmax(0,1fr));
}

.feature-card,
.section-card,
.contact-card{
  padding:24px;
}

.feature-card h3,
.section-card h3,
.sidebar-card h3,
.contact-card h3{
  margin:0 0 10px;
  font-size:1.14rem;
}

.feature-card p,
.section-card p,
.sidebar-card p,
.contact-card p{
  margin:0;
  color:var(--text-muted);
}

.homepage-content{
  width:var(--container);
  margin:0 auto;
  padding:8px 0 24px;
  display:grid;
  grid-template-columns:minmax(0,1.55fr) minmax(280px,.78fr);
  gap:24px;
}

.post-stream{
  display:grid;
  gap:18px;
}

.post-card{
  overflow:hidden;
}

.post-card-inner{
  padding:24px;
}

.post-meta{
  display:flex;
  flex-wrap:wrap;
  gap:10px;
  margin-bottom:14px;
  color:var(--text-muted);
  font-size:.92rem;
}

.post-title{
  font-size:clamp(1.45rem, 2.3vw, 2.1rem);
  margin:0 0 12px;
}

.post-excerpt{
  color:var(--text-soft);
  margin:0 0 18px;
}

.post-footer{
  display:flex;
  justify-content:space-between;
  align-items:center;
  gap:12px;
  flex-wrap:wrap;
}

.label-list{
  display:flex;
  flex-wrap:wrap;
  gap:10px;
}

.label-list a,
.chip-link{
  display:inline-flex;
  align-items:center;
  padding:8px 12px;
  border-radius:999px;
  background:var(--bg-soft);
  border:1px solid var(--line);
  color:var(--text-soft);
  transition:transform .25s ease, border-color .25s ease;
}

.label-list a:hover,
.chip-link:hover{
  transform:translateY(-1px);
  border-color:var(--line-strong);
}

.sidebar{
  display:grid;
  gap:18px;
  align-self:start;
  position:sticky;
  top:calc(var(--header-height) + 16px);
}

.sidebar-card{
  padding:22px;
}

.sidebar-list{
  list-style:none;
  margin:14px 0 0;
  padding:0;
  display:grid;
  gap:12px;
}

.sidebar-list li a{
  display:flex;
  justify-content:space-between;
  gap:10px;
  color:var(--text-soft);
}

.post-layout{
  width:var(--container);
  margin:0 auto;
  padding:40px 0 32px;
  display:grid;
  grid-template-columns:minmax(0,1.65fr) minmax(250px,.75fr);
  gap:24px;
}

.post-shell{
  padding:32px;
}

.page-hero{
  width:var(--container);
  margin:0 auto;
  padding:40px 0 16px;
}

.page-hero-card{
  padding:32px;
  background:linear-gradient(130deg, rgba(94,234,212,.08), rgba(125,211,252,.06));
  border:1px solid var(--line);
  border-radius:var(--radius);
  box-shadow:var(--shadow-soft);
}

.page-hero h1{
  font-size:clamp(2.1rem, 4vw, 4rem);
  margin:14px 0 12px;
}

.page-hero p{
  margin:0;
  color:var(--text-soft);
  max-width:70ch;
}

.page-grid{
  grid-template-columns:repeat(2, minmax(0,1fr));
}

.project-grid{
  grid-template-columns:repeat(3, minmax(0,1fr));
}

.services-grid{
  grid-template-columns:repeat(3, minmax(0,1fr));
}

.resource-grid{
  grid-template-columns:repeat(3, minmax(0,1fr));
}

.testimonial-grid{
  grid-template-columns:repeat(3, minmax(0,1fr));
}

.timeline{
  display:grid;
  gap:16px;
}

.timeline-item{
  padding:20px;
  border-radius:18px;
  background:var(--bg-soft);
  border:1px solid var(--line);
}

.timeline-item strong{
  display:block;
  margin-bottom:6px;
}

.newsletter{
  overflow:hidden;
}

.newsletter-card{
  display:grid;
  grid-template-columns:minmax(0,1.1fr) minmax(280px,.9fr);
  gap:22px;
  align-items:center;
}

.newsletter-form{
  display:flex;
  gap:12px;
  flex-wrap:wrap;
}

.newsletter-form input{
  flex:1 1 220px;
  min-height:54px;
  border-radius:16px;
  border:1px solid var(--line);
  padding:0 16px;
  background:var(--bg-soft);
  color:var(--text);
}

.newsletter-note{
  color:var(--text-muted);
  font-size:.92rem;
}

.article-content,
.comment-wrapper{
  margin-top:28px;
}

.article-content h2,
.article-content h3,
.article-content h4{
  margin:32px 0 14px;
  line-height:1.18;
}

.article-content p,
.article-content li,
.article-content blockquote{
  color:var(--text-soft);
}

.article-content a{
  color:var(--accent-2);
}

.article-content img{
  margin:28px auto;
  border-radius:22px;
  box-shadow:var(--shadow-soft);
}

.article-content pre,
.article-content code,
.code-theme{
  font-family:var(--font-code);
}

.article-content pre{
  position:relative;
  margin:24px 0;
  padding:20px 18px;
  background:#07111f;
  color:#dbeafe;
  border-radius:18px;
  overflow:auto;
  border:1px solid rgba(125,211,252,.14);
}

html.light-mode .article-content pre{
  background:#e8f0ff;
  color:#0f172a;
}

.article-content :not(pre) > code{
  padding:3px 8px;
  border-radius:8px;
  background:var(--bg-soft);
  color:var(--accent-2);
}

.toc{
  padding:20px;
  border-radius:18px;
  background:var(--bg-soft);
  border:1px solid var(--line);
}

.toc strong{
  display:block;
  margin-bottom:12px;
}

.toc ul{
  list-style:none;
  margin:0;
  padding:0;
  display:grid;
  gap:10px;
}

.toc a{
  color:var(--text-soft);
}

.contact-grid{
  display:grid;
  grid-template-columns:repeat(2, minmax(0,1fr));
  gap:18px;
}

.contact-card ul{
  list-style:none;
  margin:14px 0 0;
  padding:0;
  display:grid;
  gap:10px;
}

.footer{
  width:var(--container);
  margin:24px auto 40px;
  padding:28px;
  border-radius:28px;
  background:var(--surface);
  border:1px solid var(--line);
  box-shadow:var(--shadow-soft);
}

.footer-grid{
  grid-template-columns:1.2fr .8fr .8fr;
}

.footer p,
.footer a,
.footer li{
  color:var(--text-muted);
}

.footer ul{
  list-style:none;
  margin:0;
  padding:0;
  display:grid;
  gap:10px;
}

.footer-bottom{
  margin-top:24px;
  padding-top:18px;
  border-top:1px solid var(--line);
  display:flex;
  justify-content:space-between;
  gap:12px;
  flex-wrap:wrap;
  color:var(--text-muted);
}

.hidden{
  display:none!important;
}

@media (max-width: 1100px){
  .hero,
  .homepage-content,
  .post-layout,
  .newsletter-card,
  .footer-grid{
    grid-template-columns:1fr;
  }

  .project-grid,
  .services-grid,
  .resource-grid,
  .testimonial-grid,
  .feature-grid,
  .page-grid,
  .contact-grid{
    grid-template-columns:repeat(2, minmax(0,1fr));
  }

  .sidebar{
    position:static;
  }
}

@media (max-width: 760px){
  :root{
    --container:min(100% - 20px, 1180px);
    --header-height:auto;
  }

  .nav-wrap{
    padding:14px 0;
    align-items:flex-start;
    flex-direction:column;
  }

  .nav-actions,
  .nav-links,
  .hero-actions,
  .newsletter-form{
    width:100%;
  }

  .nav-links{
    overflow:auto;
    padding-bottom:2px;
    flex-wrap:nowrap;
  }

  .nav-link{
    white-space:nowrap;
  }

  .hero-panel,
  .hero-side,
  .post-card-inner,
  .post-shell,
  .feature-card,
  .section-card,
  .sidebar-card,
  .contact-card,
  .page-hero-card,
  .footer{
    padding:20px;
  }

  .metric-grid,
  .project-grid,
  .services-grid,
  .resource-grid,
  .testimonial-grid,
  .feature-grid,
  .page-grid,
  .contact-grid{
    grid-template-columns:1fr;
  }

  .section-heading{
    align-items:flex-start;
    flex-direction:column;
  }

  .footer-bottom,
  .post-footer{
    align-items:flex-start;
    flex-direction:column;
  }
}

body.script:
(function(){
  var root = document.documentElement;
  var storedTheme = '';
  try { storedTheme = localStorage.getItem('codewithalbin-theme') || ''; } catch (e) {}
  var prefersLight = window.matchMedia && window.matchMedia('(prefers-color-scheme: light)').matches;
  if (storedTheme === 'light' || (!storedTheme && prefersLight)) {
    root.classList.add('light-mode');
  }

  var themeToggle = document.getElementById('themeToggle');
  function syncThemeLabel(){
    if (!themeToggle) { return; }
    themeToggle.textContent = root.classList.contains('light-mode') ? 'Dark' : 'Light';
  }
  syncThemeLabel();
  if (themeToggle) {
    themeToggle.addEventListener('click', function(){
      root.classList.toggle('light-mode');
      try { localStorage.setItem('codewithalbin-theme', root.classList.contains('light-mode') ? 'light' : 'dark'); } catch (e) {}
      syncThemeLabel();
    });
  }

  var searchToggle = document.getElementById('searchToggle');
  var searchPanel = document.getElementById('searchPanel');
  if (searchToggle && searchPanel) {
    searchToggle.addEventListener('click', function(){
      var visible = searchPanel.classList.toggle('is-visible');
      searchToggle.setAttribute('aria-expanded', visible ? 'true' : 'false');
    });
  }

  var articleContent = document.getElementById('articleContent');
  var tocList = document.getElementById('tocList');
  if (articleContent && tocList) {
    var headings = articleContent.querySelectorAll('h2, h3');
    if (headings.length) {
      tocList.innerHTML = '';
      for (var i = 0; i < headings.length; i++) {
        var heading = headings[i];
        if (!heading.id) {
          heading.id = 'section-' + (i + 1);
        }
        var li = document.createElement('li');
        var link = document.createElement('a');
        link.href = '#' + heading.id;
        link.textContent = heading.textContent;
        li.appendChild(link);
        tocList.appendChild(li);
      }
    }

    var blocks = articleContent.querySelectorAll('pre');
    for (var j = 0; j < blocks.length; j++) {
      var pre = blocks[j];
      if (pre.querySelector('.copy-button')) { continue; }
      var button = document.createElement('button');
      button.className = 'copy-button';
      button.type = 'button';
      button.textContent = 'Copy';
      button.style.position = 'absolute';
      button.style.top = '12px';
      button.style.right = '12px';
      button.addEventListener('click', (function(block, btn){
        return function(){
          var text = block.innerText;
          if (!navigator.clipboard) { return; }
          navigator.clipboard.writeText(text).then(function(){
            var original = btn.textContent;
            btn.textContent = 'Copied';
            setTimeout(function(){ btn.textContent = original; }, 1600);
          });
        };
      })(pre, button));
      pre.appendChild(button);
    }
  }
})();
